// ============================================================
// Animation timeline math.
//
// Pure functions — no DOM, no React, no browser APIs. Given a normalised
// progress value t in [0,1], returns what each layer should look like at that
// instant. anim-dom.ts turns these into inline styles; nothing else here knows
// about elements.
// ============================================================

import type { MotionId, MotionPreset } from "./types";

// ---- Easing ----

/** Decelerating ease. Fast out of the gate, settles softly. */
export function easeOutCubic(x: number): number {
  return 1 - Math.pow(1 - x, 3);
}

/** Gentle both ends — used for background motion, which should never snap. */
export function easeInOutSine(x: number): number {
  return -(Math.cos(Math.PI * x) - 1) / 2;
}

/**
 * Decelerating ease that overshoots past 1 before settling — a layer lands
 * past its resting position and springs back, instead of just arriving.
 * `overshoot` is the standard back-ease constant; higher springs further.
 */
export function easeOutBack(x: number, overshoot: number): number {
  const c1 = overshoot;
  const c3 = c1 + 1;
  const p = x - 1;
  return 1 + c3 * p * p * p + c1 * p * p;
}

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);

// ---- Presets ----
//
// Bands are fractions of t, not seconds, so changing the duration stretches
// the whole timeline proportionally rather than leaving a fixed-length
// entrance inside a longer slide.

