// ---- State at a point in time ----

export interface LayerState {
  opacity: number;
  translateX: number;
  translateY: number;
  scale: number;
}

export interface BackgroundState {
  scale: number;
  driftX: number;
  driftY: number;
}

/**
 * Where text layer `staggerIndex` sits at progress `t`.
 * Layer 0 starts immediately; each subsequent layer is offset by `stagger`.
 */
export function layerStateAt(
  t: number,
  staggerIndex: number,
  preset: MotionPreset,
  layerCount = 1
): LayerState {
  // Spread the layers so the last one finishes exactly at entranceEnd. Using a
  // fixed per-layer offset instead would make a 3-layer slide finish in a third
  // of the time of a 9-layer one, and the deck would read as inconsistent.
  const span = Math.max(0, preset.entranceEnd - preset.layerDuration);
  const stagger = layerCount > 1 ? Math.min(preset.stagger, span / (layerCount - 1)) : 0;

  const start = staggerIndex * stagger;
  const local = clamp01((t - start) / preset.layerDuration);

  // Overshoot presets (stamp) use a back-ease for the transform so a layer
  // lands past rest and springs back; the three original presets have no
  // overshoot and fall back to the exact easeOutCubic curve they always used.
  const overshoot = preset.overshoot ?? 0;
  const landEase = overshoot > 0 ? easeOutBack(local, overshoot) : easeOutCubic(local);

  // Opacity can saturate faster than the transform settles — a filled panel
  // half-see-through on top of its own background reads as broken, not
  // mid-entrance. opacityBoost defaults to 1, which ties opacity to the same
  // curve as translateY/scale, exactly matching pre-stamp behavior.
  const opacityBoost = preset.opacityBoost ?? 1;
  const opacity = clamp01(easeOutCubic(Math.min(1, local * opacityBoost)));

  // Travel direction alternates by layer so a deck with multiple panelled
  // layers (list/stat items, once panels are used there) doesn't stamp every
  // layer in from the same side. A single-panel slide just gets one direction.
  const dirSign = staggerIndex % 2 === 0 ? 1 : -1;

  return {
    opacity,
    translateX: dirSign * (preset.travelXFrom ?? 0) * (1 - landEase),
    translateY: preset.riseFrom * (1 - landEase),
    scale: preset.scaleFrom + (1 - preset.scaleFrom) * landEase,
  };
}

/**
 * Background motion runs across the whole timeline, independent of the text
 * entrance — that separation is what keeps a slide from reading as a build.
 */
export function backgroundStateAt(t: number, preset: MotionPreset): BackgroundState {
  const eased = easeInOutSine(clamp01(t));
  return {
    scale: preset.bgScaleFrom + (preset.bgScaleTo - preset.bgScaleFrom) * eased,
    driftX: -preset.bgDriftPx * eased,
    driftY: preset.bgDriftPx * 0.4 * eased,
  };
}

/** Frame count for a duration at a fixed frame rate. */
export function frameCount(durationSec: number, fps: number): number {
  return Math.max(2, Math.round(durationSec * fps));
}
